import{_ as i,C as c,o as n,c as s,j as d,a as e,E as o,aj as r}from"./chunks/framework.m090XgxO.js";const P=JSON.parse('{"title":"TagGroup","description":"","frontmatter":{},"headers":[],"relativePath":"components/tag-group.md","filePath":"components/tag-group.md","lastUpdated":1789206102000}'),h={name:"components/tag-group.md"},g={id:"taggroup",tabindex:"-1"};function u(p,t,b,m,f,x){const l=c("Badge"),a=c("XhDemo");return n(),s("div",null,[d("h1",g,[t[0]||(t[0]=e("TagGroup ",-1)),o(l,{type:"info",text:"标签组"}),t[1]||(t[1]=e()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#taggroup","aria-label":'Permalink to "TagGroup <Badge type="info" text="标签组" />"'},"​",-1))]),t[3]||(t[3]=r('<p>一排标签当作一件东西来操作：方向键在标签之间走，整组只占一个 Tab 停靠点， 标签可以选中、也可以被摘掉，摘完焦点有去处。</p><p>单枚<a href="./tag">标签</a>不接收焦点，它的关闭钮是页面上一个独立的 Tab 停靠点——十枚标签就是 十个停靠点，键盘用户得按十下才能走过去。标签组把这十个收成一个。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/tag-group" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/tag-group.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/tag-group" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/tag-group" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/tag-group.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>一排可摘标签，每一枚都是库里的 tag：整组只占一个 Tab 位，方向键走标签，Delete 或 Backspace 摘掉，那颗叉就是 tag 的 close-trigger</p>',5)),o(a,{src:"tag-group/01-basic"}),t[4]||(t[4]=d("h2",{id:"示例",tabindex:"-1"},[e("示例 "),d("a",{class:"header-anchor",href:"#示例","aria-label":'Permalink to "示例"'},"​")],-1)),t[5]||(t[5]=d("h3",{id:"可选中",tabindex:"-1"},[e("可选中 "),d("a",{class:"header-anchor",href:"#可选中","aria-label":'Permalink to "可选中"'},"​")],-1)),t[6]||(t[6]=d("p",null,"selectionMode 决定点一枚是替换还是加选；Ctrl/Cmd + A 全选",-1)),o(a,{src:"tag-group/02-selection"}),t[7]||(t[7]=d("h3",{id:"尺寸",tabindex:"-1"},[e("尺寸 "),d("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),t[8]||(t[8]=d("p",null,"size 打在组上逐枚落到每一枚标签上，走 tag 的三档，标签自己不写档位",-1)),o(a,{src:"tag-group/03-size"}),t[9]||(t[9]=d("h3",{id:"手写部件",tabindex:"-1"},[e("手写部件 "),d("a",{class:"header-anchor",href:"#手写部件","aria-label":'Permalink to "手写部件"'},"​")],-1)),t[10]||(t[10]=d("p",null,"逐部件自己写，标签里就能塞头像、计数这类自带内容，摘除钮照旧归 cell 管；条目渲出来是 tag 的 root、文字是 tag 的 label，产出的结构与只交数据那一份完全一致，Tab 位与键盘也一样",-1)),o(a,{src:"tag-group/04-parts"}),t[11]||(t[11]=r('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>一排可摘的标签：已生效的筛选条件、一条记录挂着的若干分类。</li><li>一排可选的标记：点一枚就筛一次，或者按住多选。</li><li>键盘与读屏用户要能逐枚走过去、逐枚摘掉。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>只有一枚标签，且不接交互：直接用<a href="./tag">标签</a>。</li><li>用户要自己输入并累积多个值：用<a href="./tags-input">标签输入</a>，它自带输入框与增删逻辑。</li><li>选项很多、需要搜索：用<a href="./select">选择器</a>的多选或<a href="./transfer">穿梭框</a>。</li><li>一组互斥选项要用户挑一个：用<a href="./radio-group">单选组</a>或<a href="./segmented">分段控件</a>。</li><li>只是把一排标签摆开、不接键盘：用<a href="./flex">弹性布局</a> 包一层就够了。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>roving tabindex：整组一个 Tab 停靠点，组内走方向键；<code>Home</code> / <code>End</code> 到端点。</li><li><code>selectionMode</code> 三档：<code>none</code> 只是标记、<code>single</code> 单选、<code>multiple</code> 可多选（<code>Ctrl</code>/<code>Cmd</code> + <code>A</code> 全选）。</li><li>每一枚标签就是库里的<a href="./tag">标签</a>：标签本体是它的 <code>root</code>，文字是它的 <code>label</code>，摘除钮是它的 <code>close-trigger</code>；组只往上面叠行角色、Tab 停靠点、选中与锚点。</li><li><code>deletable</code> 给出摘除钮，键盘那一路走 <code>Delete</code> / <code>Backspace</code>。</li><li>选择与摘除是两个互斥动作：点标签本体才选择，点摘除钮只从选中集合移除并发 <code>item-delete</code>， 不会让同一次冒泡 click 又把待删值选回来。</li><li>摘掉一枚之后焦点交给前一枚；前面没有就交给后一枚，一枚不剩就交给列表容器。</li><li><code>collection</code> 是文本、禁用与可摘的事实源；也可以逐枚自己写。</li><li>连打检索按首字母跳，只搬焦点、不改选中值。</li></ul><h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-tag-group&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhTagGroupCell</code> <code>XhTagGroupItem</code> <code>XhTagGroupItemDeleteTrigger</code> <code>XhTagGroupItemText</code> <code>XhTagGroupLabel</code> <code>XhTagGroupList</code> <code>XhTagGroupRoot</code></td></tr><tr><td>组合式函数</td><td><code>useTagGroup</code></td></tr><tr><td>状态机</td><td><code>tagGroupMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/tag-group.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;tag-group&quot;</code>：<code>root</code> · <code>label</code> · <strong><code>list</code></strong> · <strong><code>cell</code></strong></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>collection</code></td><td><code>TagGroupNode[]</code></td><td></td><td>条目数据，显示文本、禁用与可摘的事实源。给了它，条目部件只需报 value。 缺省即回到「文本与禁用都写在条目部件上」的老路。</td></tr><tr><td><code>value</code></td><td><code>string | string[]</code></td><td></td><td>选中值，给定即受控；单选可写成裸串，内部归一成数组。</td></tr><tr><td><code>defaultValue</code></td><td><code>string | string[]</code></td><td></td><td></td></tr><tr><td><code>selectionMode</code></td><td><code>TagGroupSelectionMode</code></td><td></td><td>选择模式，默认 none。</td></tr><tr><td><code>deletable</code></td><td><code>boolean</code></td><td></td><td>是否给出摘除钮，默认 false。false 时该钮同时被禁用与收起。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>整组禁用：键盘与点击都不再改选中值，也摘不掉任何一枚。</td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td><td>只读：仍可聚焦、可导航与朗读，但选中值改不动、标签也摘不掉。</td></tr><tr><td><code>loop</code></td><td><code>boolean</code></td><td></td><td>方向键走到尽头是否回绕，默认 true。</td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向，默认 ltr。</td></tr><tr><td><code>orientation</code></td><td><code>Orientation</code></td><td></td><td>方向键轴向，默认 horizontal——标签是成排出现的。</td></tr><tr><td><code>typeahead</code></td><td><code>boolean</code></td><td></td><td>连打检索，默认开。</td></tr><tr><td><code>variant</code></td><td><code>TagVariant</code></td><td></td><td>形态：solid / subtle / outline，逐枚落到每一枚标签（tag 的 root）上。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定用哪族颜色。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg，走 tag 的三档。</td></tr><tr><td><code>onValueChange</code></td><td><code>(details: TagGroupValueChangeDetails) =&gt; void</code></td><td></td><td>value 变化意图回调。</td></tr><tr><td><code>onItemDelete</code></td><td><code>(details: TagGroupItemDeleteDetails) =&gt; void</code></td><td></td><td>摘除意图回调。条目由宿主的数据决定去留，组件只报「用户要摘这一枚」， 顺手把它从选中集合里去掉，并把焦点交给相邻的一枚。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;TagGroupTranslations&gt;</code></td><td></td><td></td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>value-change</code></td><td><code>TagGroupValueChangeDetails</code></td><td>选中集合变化；detail 为 <code>{ value: string[] }</code></td></tr><tr><td><code>item-delete</code></td><td><code>TagGroupItemDeleteDetails</code></td><td>用户要摘掉某一枚；detail 为 <code>{ value: string }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhTagGroupRoot</code></td><td><code>default</code></td><td><code>TagGroupRootSlotProps</code></td><td></td></tr><tr><td><code>XhTagGroupRoot</code></td><td><code>label</code></td><td>—</td><td></td></tr><tr><td><code>XhTagGroupRoot</code></td><td><code>item</code></td><td><code>TagGroupNodeMeta</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>idle</code></p><p><strong>事件</strong>：<code>VALUE.SET</code> · <code>ITEM.SELECT</code> · <code>ITEM.TOGGLE</code> · <code>ITEM.FOCUS</code> · <code>ITEM.DELETE</code> · <code>LIST.BLUR</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useTagGroup</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>string[]</code></td><td>选中集合；单选模式下长度 ≤ 1。</td></tr><tr><td><code>collection</code></td><td><code>readonly TagGroupNodeMeta[]</code></td><td>collection 推出的条目元信息，按数据顺序排列；没给 collection 即空数组。</td></tr><tr><td><code>selectionMode</code></td><td><code>TagGroupSelectionMode</code></td><td>生效的选择模式。</td></tr><tr><td><code>focusedValue</code></td><td><code>string | null</code></td><td>焦点锚点；焦点不在组内时为 null。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>deletable</code></td><td><code>boolean</code></td><td>整组是否给出摘除钮。</td></tr><tr><td><code>isSelected</code></td><td><code>(value: string) =&gt; boolean</code></td><td></td></tr><tr><td><code>setValue</code></td><td><code>(next: string[]) =&gt; void</code></td><td></td></tr><tr><td><code>select</code></td><td><code>(value: string) =&gt; void</code></td><td>只留这一个；加选用 toggle。</td></tr><tr><td><code>toggle</code></td><td><code>(value: string) =&gt; void</code></td><td></td></tr><tr><td><code>deleteItem</code></td><td><code>(value: string) =&gt; void</code></td><td>摘掉一枚。程序化入口，不搬焦点。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLabelProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getListProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(props: TagGroupItemProps) =&gt; T[&#39;element&#39;]</code></td><td>一枚标签：库里 tag 的 root（data-scope=&quot;tag&quot;），三轴与置灰由 tag 给； row 角色、身份、roving tabindex、选中（data-selected）与锚点（data-highlighted）叠在它上面。</td></tr><tr><td><code>getCellProps</code></td><td><code>(props: TagGroupItemProps) =&gt; T[&#39;element&#39;]</code></td><td>标签里那一格；摘除钮必须落在它之内。</td></tr><tr><td><code>getItemTextProps</code></td><td><code>(props: TagGroupItemProps) =&gt; T[&#39;element&#39;]</code></td><td>标签文字：tag 的 label，截断规则挂在那一层。</td></tr><tr><td><code>getItemDeleteTriggerProps</code></td><td><code>(props: TagGroupItemProps) =&gt; T[&#39;button&#39;]</code></td><td>摘除钮：所在标签那份 tag 的 close-trigger，不占 Tab 位；可及名、禁用与收起都由 tag 给。</td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/grid/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>focus outside the group</td><td>整组只占一个 Tab 位：焦点进入锚点标签，无锚点时先落列表容器再由它转投；每枚标签的摘除钮一律不占停靠点</td></tr><tr><td><code>ArrowRight</code></td><td>focus in group, orientation=horizontal</td><td>焦点移到下一枚可停留标签（禁用项跳过、尽头按 loop 回绕）；orientation=vertical 时改由 ArrowDown 承担，dir=rtl 再对调左右</td></tr><tr><td><code>ArrowLeft</code></td><td>focus in group, orientation=horizontal</td><td>焦点移到上一枚可停留标签（禁用项跳过、尽头按 loop 回绕）；orientation=vertical 时改由 ArrowUp 承担，dir=rtl 再对调左右</td></tr><tr><td><code>Home</code></td><td>focus in group</td><td>焦点移到首枚可停留标签</td></tr><tr><td><code>End</code></td><td>focus in group</td><td>焦点移到末枚可停留标签</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>focus on item, selectionMode=single 且可改</td><td>只选中焦点标签，替换原有选中；标签禁用或整组只读则不认</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>focus on item, selectionMode=multiple 且可改</td><td>切换焦点标签的选中态，其余选中不动</td></tr><tr><td><code>Ctrl+A</code> / <code>Cmd+A</code></td><td>focus in group, selectionMode=multiple 且可改</td><td>选中全部可选标签；已经全选则把它们一并取消（禁用但已选中的不动）</td></tr><tr><td><code>Delete</code> / <code>Backspace</code></td><td>focus on item, 该标签可摘且可改</td><td>摘掉焦点标签，并把焦点交给前一枚；前面没有就交给后一枚，一枚不剩就交给列表容器</td></tr><tr><td><code>单个可打印字符</code></td><td>focus in group, typeahead 未关</td><td>连打检索把焦点移到首字母匹配的标签，不改选中值</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>list</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>list</code></td><td><code>aria-label</code></td><td>label.list</td></tr><tr><td><code>list</code></td><td><code>aria-labelledby</code></td><td><code>label</code> 部件的 id</td></tr><tr><td><code>list</code></td><td><code>aria-multiselectable</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>list</code></td><td><code>aria-readonly</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>list</code></td><td><code>role</code></td><td>&#39;grid&#39;</td></tr><tr><td><code>cell</code></td><td><code>role</code></td><td>&#39;gridcell&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-selected</code></td><td>&#39;true&#39; | &#39;false&#39; | undefined</td></tr><tr><td><code>item</code></td><td><code>role</code></td><td>&#39;row&#39;</td></tr></tbody></table><p>一排可摘标签是「集合 + 每条自带动作」，这在 ARIA 里只有表格语义放得下：可聚焦的摘除钮 不许待在 <code>option</code> 这类控件角色里，<code>gridcell</code> 允许。所以 <code>list</code> 是 <code>grid</code>、每枚标签（<a href="./tag">标签</a>的 <code>root</code>） 担 <code>row</code>、标签里那一格是 <code>gridcell</code>——手写部件时 <code>cell</code> 这一层不能省，用 <code>collection</code> 则由组件自己铺开。</p><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/tag-group.css</code> 按部件选择：<code>[data-scope=&quot;tag-group&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>root</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>label</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>list</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>list</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>item</code></td><td><code>data-deletable</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-selectable</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；缺省来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>缺省来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-tag-group-gap</code></td><td><code>root</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-2</code></td><td>tag-group 的 root 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-tag-group-item-bg-hover</code></td><td><code>list</code><br><code>root</code></td><td><code>background</code></td><td><code>disabled</code><br><code>highlighted</code><br><code>is(:hover, [data-highlighted])</code><br><code>not([data-disabled])</code><br><code>not([data-variant=&#39;solid&#39;])</code><br><code>variant=solid</code></td><td><code>--xh-bg-subtle-hover</code></td><td>tag-group 的 list、root 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-tag-group-item-border-selected</code></td><td><code>list</code><br><code>root</code></td><td><code>border-color</code></td><td><code>disabled</code><br><code>not([data-disabled])</code><br><code>not([data-variant=&#39;solid&#39;])</code><br><code>selected</code><br><code>variant=solid</code></td><td><code>--xh-_tone</code><br><code>currentColor</code></td><td>tag-group 的 list、root 部件 border-color 覆盖槽。</td></tr><tr><td><code>--xh-tag-group-item-fg-selected</code></td><td><code>list</code><br><code>root</code></td><td><code>color</code></td><td><code>disabled</code><br><code>not([data-disabled])</code><br><code>not([data-variant=&#39;solid&#39;])</code><br><code>selected</code><br><code>variant=solid</code></td><td><code>--xh-_tone-fg</code></td><td>tag-group 的 list、root 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-tag-group-label-fg</code></td><td><code>label</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-muted</code></td><td>tag-group 的 label 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-tag-group-label-font-size</code></td><td><code>label</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-text-label-size</code></td><td>tag-group 的 label 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-tag-group-label-font-weight</code></td><td><code>label</code></td><td><code>font-weight</code></td><td><code>default</code></td><td><code>--xh-text-label-weight</code></td><td>tag-group 的 label 部件 font-weight 覆盖槽。</td></tr><tr><td><code>--xh-tag-group-list-gap</code></td><td><code>list</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-1_5</code></td><td>tag-group 的 list 部件 gap 覆盖槽。</td></tr></tbody></table><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p><code>background</code> · <code>color</code> · <code>scale</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>每一枚标签就是<a href="./tag">标签</a>本身：形态 · 语气 · 尺寸三轴写在组上，逐枚落到每一枚的 <code>root</code> 上，样子全归 <code>tag.css</code>，<code>--xh-tag-*</code> 覆盖槽在组里照样生效。</li><li>标签里的图元用<a href="./icon">图标</a>。</li><li>外面套<a href="./field">表单字段</a>，标题就有了去处。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>条目的去留是宿主的事：<code>item-delete</code> 只报「用户要摘这一枚」，宿主从自己的数据里删掉它。 组件不替宿主决定，因为撤销、二次确认、服务端失败回滚都只有宿主知道。</li><li>摘掉一枚之后要有回退路径，否则用户误点就再也加不回来。</li><li>标签文字尽量短，且首字母有区分度——连打检索按首字母跳。</li><li>不接选中就把 <code>selectionMode</code> 留在 <code>none</code>：一排纯标记标签报「未选中」是句假话。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>把整排标签铺成十个 Tab 停靠点：那正是这个组件要解决的问题，别再逐枚写<a href="./tag">标签</a>。</li><li>摘完不管焦点：被摘的那一枚带着焦点一起消失，焦点会掉回页面开头。</li><li>用颜色单独表达含义：色觉障碍的用户分不出来，文字本身要说清楚。</li></ul>',51))])}const q=i(h,[["render",u]]);export{P as __pageData,q as default};
